// Synthetic unshown WPF verification; no device, scenario repository IO, dialogs,
// program launching or native window creation. Executor/transport methods are not run.
using System;using System.Collections.Generic;using System.IO;using System.Linq;using System.Reflection;using System.Threading;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Interop;using System.Windows.Media;using RogControl;
internal static class ScenarioGuiTests {
 static readonly BindingFlags Hidden=BindingFlags.Instance|BindingFlags.NonPublic;static int Count;
 static void Check(bool value,string name){if(!value)throw new Exception("FAIL "+name);Count++;}
 static object Get(MainWindow window,string name){return typeof(MainWindow).GetField(name,Hidden).GetValue(window);}
 static void Set(MainWindow window,string name,object value){typeof(MainWindow).GetField(name,Hidden).SetValue(window,value);}
 static void Invoke(MainWindow window,string name,params object[] args){typeof(MainWindow).GetMethod(name,Hidden).Invoke(window,args);}
 static IEnumerable<DependencyObject> Walk(DependencyObject node){yield return node;foreach(object item in LogicalTreeHelper.GetChildren(node)){var child=item as DependencyObject;if(child!=null)foreach(var next in Walk(child))yield return next;}}
 static List<FrameworkElement> Nodes(MainWindow window){return Walk((DependencyObject)Get(window,"content")).OfType<FrameworkElement>().ToList();}
 static T Tagged<T>(MainWindow window,string tag) where T:FrameworkElement{return Nodes(window).OfType<T>().Single(element=>Convert.ToString(element.Tag)==tag);}
 static Rect Bounds(MainWindow window,FrameworkElement node){return node.TransformToAncestor((FrameworkElement)window.Content).TransformBounds(new Rect(0,0,node.ActualWidth,node.ActualHeight));}
 static void NoNative(MainWindow window,string repository){Check(new WindowInteropHelper(window).Handle==IntPtr.Zero,"no HWND");foreach(var field in typeof(MainWindow).GetFields(Hidden).Where(field=>field.FieldType==typeof(WorkerClient)))Check(typeof(WorkerClient).GetField("process",Hidden).GetValue((WorkerClient)field.GetValue(window))==null,"no worker created: "+field.Name);Check(!Directory.Exists(repository),"no scenario repository created");Check(!window.ScenarioFeaturesActive,"no scenario execution");}
 static ScenarioProfile Draft(){var profile=new ScenarioProfile{Name="Synthetic Scenario"};profile.Applications.Add(new ScenarioApplication{Name="Synthetic Game",SteamId="12345"});foreach(string kind in new[]{"keyboard","mouse","headset"})profile.Devices.Add(new ScenarioDeviceProfile{Kind=kind,DeviceId="synthetic-"+kind,Name="Synthetic "+kind,CapturedAt=new DateTime(2026,1,1),Settings=new List<ScenarioSetting>{new ScenarioSetting{Setting=kind=="headset"?"latencyMs":"pollingRate",Value=kind=="headset"?60:1000}}});foreach(string flow in new[]{"render","capture"})profile.Audio.Add(new ScenarioAudioProfile{Flow=flow,EndpointId="synthetic-"+flow,Name="Synthetic "+flow,Volume=40,ObservedVolumePercent=40.2,Muted=false});return profile;}
 static void Render(MainWindow window,int width){Invoke(window,"ShowPage","情境设置档");((ScrollViewer)Get(window,"pageScroll")).ScrollToTop();var frame=(FrameworkElement)window.Content;int height=width==1538?826:726;frame.Measure(new Size(width,height));frame.Arrange(new Rect(0,0,width,height));frame.UpdateLayout();}
 [STAThread]public static int Main(){try{new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var window=new MainWindow(true);string repository=Path.Combine(Path.GetTempPath(),"OpenAC-ScenarioGuiTests-"+Guid.NewGuid().ToString("N"));Set(window,"scenarioRepository",new ScenarioRepository(repository));Set(window,"scenarioLoaded",false);var sentinel=Draft();Set(window,"scenarioFiles",new List<ScenarioProfile>{sentinel});Set(window,"games",new List<GameEntry>{new GameEntry{Id="synthetic",Name="Synthetic Game",SteamId="12345"}});Set(window,"scenarioDraft",new ScenarioProfile());
  foreach(int width in new[]{1538,1180}) {
   Render(window,width);Check((bool)Get(window,"scenarioLoaded"),"render initializes page memory");Check(((List<ScenarioProfile>)Get(window,"scenarioFiles")).Single().Id==sentinel.Id,"render does not reload user's scenario files");var nodes=Nodes(window);var surface=Tagged<Canvas>(window,"scenario:surface");var apps=Tagged<Border>(window,"scenario:applications");Check(Math.Abs(Bounds(window,surface).Top-72)<0.1,"fixed scenario body origin72");Check(apps.Width==376&&apps.Height==525,"application box376x525");Check(Math.Abs(Canvas.GetLeft(apps)-35)<0.1&&Math.Abs(Canvas.GetTop(apps)-104)<0.1,"application box native relative origin");var rows=nodes.OfType<Canvas>().Where(element=>Convert.ToString(element.Tag).StartsWith("scenario:device:")).ToArray();Check(rows.Select(element=>Convert.ToString(element.Tag)).SequenceEqual(new[]{"scenario:device:keyboard","scenario:device:mouse","scenario:device:headset"}),"device rows keyboard mouse headset");Check(rows.All(element=>element.Width==747&&element.Height==52),"three native horizontal rows");Check(nodes.OfType<ComboBox>().Where(element=>Convert.ToString(element.Tag).StartsWith("scenario:deviceChoice:")).All(element=>!element.IsEnabled&&Convert.ToString(element.SelectedItem)=="尚未捕获"),"uncaptured profiles are not fabricated hardware profiles");Check(nodes.OfType<Button>().Count(element=>Convert.ToString(element.Content)=="读取并捕获")==5,"existing five capture entry points preserved");Check(nodes.OfType<Button>().Where(element=>Convert.ToString(element.Content)=="读取并捕获").All(element=>!element.IsEnabled),"render capture disabled");Check(!Tagged<Button>(window,"scenario:save").IsEnabled&&!Tagged<Button>(window,"scenario:apply").IsEnabled,"render save/apply disabled");Check(!nodes.OfType<CheckBox>().Any(element=>element.IsChecked.HasValue),"unsupported cache switch unknown");Check(nodes.OfType<Canvas>().Count(element=>Convert.ToString(element.Tag).StartsWith("scenario:unsupported:"))==2,"two unsupported application rows");Check(nodes.OfType<ComboBox>().All(element=>!(element.Background is SolidColorBrush)||((SolidColorBrush)element.Background).Color!=Colors.White),"no white combos");
   var viewer=nodes.OfType<ScrollViewer>().Single(element=>element.Content==surface);Check(width==1538?viewer.ScrollableWidth<=18:viewer.ScrollableWidth>300,"body preserves native width with local scroll");viewer.ScrollToRightEnd();((ScrollViewer)Get(window,"pageScroll")).ScrollToBottom();((FrameworkElement)window.Content).UpdateLayout();Rect apply=Bounds(window,Tagged<Button>(window,"scenario:apply"));Check(apply.Left>=248&&apply.Right<=width-21&&apply.Bottom<=(width==1538?826:726)-25,"apply reachable with scrolling");var header=(StackPanel)Get(window,"fixedPageHeader");var library=Walk(header).OfType<Button>().Single(element=>Convert.ToString(element.Tag)=="scenario:library");Check(Bounds(window,library).Right<=width-21,"library remains reachable in narrow header");library.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(!library.ContextMenu.IsOpen,"render cannot open popup/window");NoNative(window,repository);
  }
  var draft=Draft();Check(ScenarioRules.BuildPlan(draft).Count==7,"valid nonempty scenario fixture before write-gate tests");Set(window,"scenarioDraft",draft);Render(window,1538);var keyboard=Tagged<ComboBox>(window,"scenario:deviceChoice:keyboard");Check(keyboard.IsEnabled&&keyboard.SelectedIndex==1,"captured local draft selection");keyboard.SelectedIndex=0;Check(!draft.Devices.First(device=>device.Kind=="keyboard").Enabled,"choice only changes local enabled flag");Tagged<CheckBox>(window,"scenario:includeLighting").IsChecked=false;Check(!draft.Devices.First(device=>device.Kind=="headset").IncludeLighting,"lighting inclusion changes local draft");Tagged<TextBox>(window,"scenario:name").Text="Edited locally";Check(draft.Name=="Edited locally","name changes local draft only");NoNative(window,repository);
  foreach(var button in Nodes(window).OfType<Button>().Where(element=>Convert.ToString(element.Tag).StartsWith("scenario:capture:")||Convert.ToString(element.Tag).StartsWith("scenario:captureAudio:")||Convert.ToString(element.Tag).StartsWith("scenario:edit:")||Convert.ToString(element.Tag).StartsWith("scenario:editAudio:")||Convert.ToString(element.Tag)=="scenario:save"||Convert.ToString(element.Tag)=="scenario:apply").ToArray())button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));NoNative(window,repository);Check(draft.SavedAt==DateTime.MinValue,"render callbacks do not save draft");
  var policy=(HardwareControlPolicy)Get(window,"hardwareControlPolicy");policy.SetEnabled(true);Render(window,1538);Check(!Tagged<Button>(window,"scenario:apply").IsEnabled,"session enable cannot override render-only");Tagged<Button>(window,"scenario:apply").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));NoNative(window,repository);policy.SetEnabled(false);
  Tagged<Button>(window,"scenario:appOptions").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check((bool)Get(window,"scenarioAppOptionsOpen"),"application options local navigation");var appCheck=Nodes(window).OfType<CheckBox>().Single(element=>Convert.ToString(element.Content)=="Synthetic Game");appCheck.IsChecked=false;Check(draft.Applications.Count==0,"association checkbox local draft only");Tagged<TextBox>(window,"scenario:appSearch").Text="nonexistent";Check(!Nodes(window).OfType<CheckBox>().Any(element=>Convert.ToString(element.Content)=="Synthetic Game"),"in-memory search filters app choices");Tagged<Button>(window,"scenario:addApplication").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));NoNative(window,repository);
  Tagged<Expander>(window,"scenario:windowsAudio").IsExpanded=true;Check((bool)Get(window,"scenarioAudioExpanded"),"Windows audio expanded locally");Render(window,1180);Check(Tagged<Canvas>(window,"scenario:surface").Height>724,"expanded Windows audio makes room without row overlap");Check(Tagged<ComboBox>(window,"scenario:audioChoice:render").SelectedIndex==1,"captured playback draft retained");Tagged<ComboBox>(window,"scenario:audioChoice:render").SelectedIndex=0;Check(!draft.Audio.First(audio=>audio.Flow=="render").Enabled,"audio choice local only");NoNative(window,repository);
  var results=(List<ScenarioApplyResult>)Get(window,"scenarioResults");results.Add(new ScenarioApplyResult{Label="Synthetic",Outcome="unconfirmed",Message="Synthetic readback missing"});Render(window,1538);Tagged<Button>(window,"scenario:results").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));NoNative(window,repository);
  var busyLibrary=Walk((StackPanel)Get(window,"fixedPageHeader")).OfType<Button>().Single(element=>Convert.ToString(element.Tag)=="scenario:library");foreach(var item in busyLibrary.ContextMenu.Items.OfType<MenuItem>().Where(item=>Convert.ToString(item.Tag)=="scenario:import"||Convert.ToString(item.Tag)=="scenario:export"))item.RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));NoNative(window,repository);
  busyLibrary.ContextMenu.Items.OfType<MenuItem>().First().Items.OfType<MenuItem>().Single().RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));Check(((ScenarioProfile)Get(window,"scenarioDraft")).Id==sentinel.Id&&!Object.ReferenceEquals(Get(window,"scenarioDraft"),sentinel),"saved profile selection clones memory without autoapply");Check(results.Count==0,"another local profile does not display the previous profile's results");NoNative(window,repository);var newMenu=Walk((StackPanel)Get(window,"fixedPageHeader")).OfType<Button>().Single(element=>Convert.ToString(element.Tag)=="scenario:library").ContextMenu.Items.OfType<MenuItem>().Single(item=>Convert.ToString(item.Tag)=="scenario:new");newMenu.RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));Check(((ScenarioProfile)Get(window,"scenarioDraft")).Devices.Count==0,"new draft does not save or apply");NoNative(window,repository);
  var cancel=new CancellationTokenSource();var pending=new TaskCompletionSource<bool>();Set(window,"scenarioCancel",cancel);Set(window,"scenarioApplyTask",pending.Task);Set(window,"busy",true);Render(window,1538);Check(!Tagged<Button>(window,"scenario:save").IsEnabled&&!Tagged<Button>(window,"scenario:apply").IsEnabled,"busy actions disabled");Check(Nodes(window).OfType<Button>().Where(element=>Convert.ToString(element.Content)=="读取并捕获").All(element=>!element.IsEnabled),"busy captures disabled");Tagged<Button>(window,"scenario:stop").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(cancel.IsCancellationRequested,"stop retains explicit cancellation");Set(window,"scenarioApplyTask",null);Set(window,"scenarioCancel",null);Set(window,"busy",false);cancel.Dispose();NoNative(window,repository);
  Set(window,"closing",true);Render(window,1538);Check(!Tagged<TextBox>(window,"scenario:name").IsEnabled&&Nodes(window).OfType<Button>().Where(element=>Convert.ToString(element.Content)=="读取并捕获").All(element=>!element.IsEnabled),"closing draft/capture controls disabled");NoNative(window,repository);Console.WriteLine("PASS "+Count+" scenario GUI checks; HWND/workers/real GET/SET/scenario file writes/program launch=0");return 0;
 }catch(Exception error){Console.Error.WriteLine("FAIL after "+Count);for(Exception current=error;current!=null;current=current.InnerException)Console.Error.WriteLine(current.GetType().FullName+": "+current.Message);return 1;}}
}
